/* {name} — STM32F103C8T6 裸机模板（蓝药丸板载 LED: PC13，低电平点亮） */
#include "stm32f1xx.h"

static void delay_loop(volatile uint32_t n) { while (n--) { __asm volatile("nop"); } }

int main(void) {
  /* 使能 GPIOC 时钟 */
  RCC->APB2ENR |= RCC_APB2ENR_IOPCEN;
  /* PC13 = 推挽输出（CNF=01 通用推挽 / MODE=10 2MHz） */
  GPIOC->CRH = (GPIOC->CRH & ~(uint32_t)0xF0) | 0x20;

  for (;;) {
    GPIOC->BRR = (1U << 13);   /* 低电平 → 亮 */
    delay_loop(2000000);
    GPIOC->BSRR = (1U << 13);  /* 高电平 → 灭 */
    delay_loop(2000000);
  }
}

/* {name} — STM32F401CCU6 裸机模板（黑药丸板载 LED: PC13，低电平点亮） */
#include "stm32f4xx.h"

static void delay_loop(volatile uint32_t n) { while (n--) { __asm volatile("nop"); } }

int main(void) {
  /* 使能 GPIOC 时钟（F4 外设时钟在 AHB1） */
  RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;
  /* PC13 = 输出 */
  GPIOC->MODER = (GPIOC->MODER & ~(3U << 26)) | (1U << 26);

  for (;;) {
    GPIOC->BSRR = (1U << 13);   /* 低电平 → 亮 */
    delay_loop(1500000);
    GPIOC->BSRR = (1U << 29);   /* 高电平 → 灭 */
    delay_loop(1500000);
  }
}

